*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#15251d;color:var(--ink);font-family:var(--sans);user-select:none;-webkit-tap-highlight-color:transparent}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#182b21}#world{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 34%,rgba(5,15,12,.14) 75%,rgba(5,12,10,.48) 120%),linear-gradient(180deg,rgba(8,18,14,.34),transparent 25%,transparent 72%,rgba(7,15,13,.4)}.grain{position:absolute;inset:-50%;opacity:.055;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.27'/%3E%3C/svg%3E");animation:grain .22s steps(2) infinite}@keyframes grain{0%{transform:translate(0,0)}50%{transform:translate(1%,-1%)}100%{transform:translate(-1%,1%)}}
